    move.b  55(a0),d5
    ext.w   d5
    move.l  VisualInfo,NR+4
    move.l  VisualInfo,IR+4
    move.l  _GadToolsBase,a6
    move.l  MC68020Wnd,a0
    move.l  50(a0),a2
    move.l  a2,a0
    lea.l   NR,a1
    move.w  #8,d0
    add.w   d4,d0
    move.w  #4,d1
    add.w   d5,d1
    move.w  #258,d2
